namespace BlazorApp.Services;

public record Notification(int Id, string Message, DateTime Timestamp);

public class NotificationService
{
    private int _nextId = 1;
    private readonly List<Notification> _notifications = new();
    private readonly Lock _lock = new();

    public NotificationService()
    {
        // Seed with initial fake data
        _notifications.Add(new Notification(_nextId++, "Welcome to the notification center!", DateTime.UtcNow.AddMinutes(-10)));
        _notifications.Add(new Notification(_nextId++, "Your profile was updated successfully.", DateTime.UtcNow.AddMinutes(-5)));
        _notifications.Add(new Notification(_nextId++, "New feature: dark mode is now available.", DateTime.UtcNow.AddMinutes(-2)));
    }

    public Task<List<Notification>> GetNotificationsAsync()
    {
        lock (_lock)
        {
            return Task.FromResult(_notifications.ToList());
        }
    }

    public Task<List<Notification>> GetNotificationsSinceAsync(int lastId)
    {
        lock (_lock)
        {
            var newer = _notifications.Where(n => n.Id > lastId).ToList();

            // Simulate new notifications arriving occasionally
            if (Random.Shared.NextDouble() < 0.3)
            {
                var newNotification = new Notification(
                    _nextId++,
                    $"New activity detected at {DateTime.UtcNow:HH:mm:ss}",
                    DateTime.UtcNow);
                _notifications.Add(newNotification);
                newer.Add(newNotification);
            }

            return Task.FromResult(newer);
        }
    }
}

@page "/notifications"
@rendermode InteractiveServer
@inject BlazorApp.Services.NotificationService NotificationService
@implements IDisposable

<PageTitle>Notifications</PageTitle>

<h1>Notifications</h1>

@if (NotificationList is null)
{
    <p><em>Loading notifications...</em></p>
}
else
{
    <p>
        <span class="badge bg-primary rounded-pill">@NotificationList.Count</span>
        notification@(NotificationList.Count != 1 ? "s" : "")
    </p>

    <ul class="list-group">
        @foreach (var notification in NotificationList.OrderByDescending(n => n.Timestamp))
        {
            <li class="list-group-item d-flex justify-content-between align-items-center">
                <span>@notification.Message</span>
                <small class="text-muted">@notification.Timestamp.ToString("HH:mm:ss")</small>
            </li>
        }
    </ul>
}

@code {
    private CancellationTokenSource? _cts;

    [PersistentState]
    public List<BlazorApp.Services.Notification>? NotificationList { get; set; }

    protected override async Task OnInitializedAsync()
    {
        // Only fetch if not restored from persisted prerender state
        NotificationList ??= await NotificationService.GetNotificationsAsync();
    }

    protected override void OnAfterRender(bool firstRender)
    {
        if (firstRender)
        {
            // OnAfterRender is never called during prerender,
            // so this only runs once the page is interactive.
            _cts = new CancellationTokenSource();
            _ = PollForNotificationsAsync(_cts.Token);
        }
    }

    private async Task PollForNotificationsAsync(CancellationToken cancellationToken)
    {
        while (!cancellationToken.IsCancellationRequested)
        {
            await Task.Delay(TimeSpan.FromSeconds(5), cancellationToken);

            var lastId = NotificationList?.MaxBy(n => n.Id)?.Id ?? 0;
            var newer = await NotificationService.GetNotificationsSinceAsync(lastId);

            if (newer.Count > 0)
            {
                NotificationList ??= new();
                NotificationList.AddRange(newer);
                await InvokeAsync(StateHasChanged);
            }
        }
    }

    public void Dispose()
    {
        _cts?.Cancel();
        _cts?.Dispose();
    }
}

